        import math

def _vertices(n):
    # Regular n-gon on unit circle, counterclockwise
    return [(math.cos(2*math.pi*k/n), math.sin(2*math.pi*k/n)) for k in range(n)]

def _line_from_segment(P, Q):
    # Return normalized line coefficients (A,B,C) for Ax + By = C, with sqrt(A^2+B^2)=1
    x1,y1 = P; x2,y2 = Q
    A = y1 - y2
    B = x2 - x1
    norm = math.hypot(A, B)
    if norm == 0:
        return None
    A /= norm; B /= norm
    C = A*x1 + B*y1
    # Normalize sign to make (A,B) a canonical representative (lexicographically)
    if A < -1e-12 or (abs(A) <= 1e-12 and B < -1e-12):
        A = -A; B = -B; C = -C
    return (A, B, C)

def _intersect_lines(L1, L2):
    # L: (A,B,C) for Ax+By=C; returns (x,y) or None if parallel
    A1,B1,C1 = L1; A2,B2,C2 = L2
    det = A1*B2 - A2*B1
    if abs(det) < 1e-12:
        return None
    x = (C1*B2 - C2*B1)/det
    y = (A1*C2 - A2*C1)/det
    return (x,y)

def _point_on_segment(X, P, Q, eps=1e-9):
    # Check X lies on segment PQ
    x,y = X; x1,y1 = P; x2,y2 = Q
    # Collinearity check via area (cross product)
    vx, vy = x2 - x1, y2 - y1
    wx, wy = x - x1, y - y1
    cross = abs(vx*wy - vy*wx)
    if cross > 1e-7:  # tolerant collinearity
        return False
    # Parametric t along PQ
    denom = vx*vx + vy*vy
    if denom == 0:
        return False
    t = (wx*vx + wy*vy)/denom
    return -eps <= t <= 1+eps

